const input = $json.body ? $json : { body: $json, headers: {} };
const body = input.body || {};
const headers = input.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '');
const mcpUrl = body.mcpUrl || $env.RUNNING_API_MCP_URL || '';
if (!token) throw new Error('Falta Authorization: Bearer <jwt> en el webhook');
if (!body.requestId || !body.weekStart) throw new Error('Faltan requestId o weekStart en el body');
if (!mcpUrl) throw new Error('Falta mcpUrl en el body o RUNNING_API_MCP_URL');
const separator = mcpUrl.includes('?') ? '&' : '?';
const mcpEndpoint = mcpUrl + separator + 'access_token=' + encodeURIComponent(token);
return [{ json: { token, mcpUrl, mcpEndpoint, requestId: body.requestId, weekStart: body.weekStart, replace: body.replace === true || body.replace === 'true' } }];

const raw = typeof $json.output === 'string' ? $json.output : JSON.stringify($json.output ?? '');
let text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);
if (!text) throw new Error('El agente no devolvió un plan JSON');
const plan = JSON.parse(text);
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, plan, planJson: JSON.stringify(plan) } }];

const raw = $json?.result?.content?.[0]?.text;
let result = {};
try { result = raw ? JSON.parse(raw) : {}; } catch (e) { result = { ok: false, message: 'Respuesta MCP no es JSON: ' + raw }; }
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, saveResult: result, saved: result.ok === true, plan: result.plan || null, failError: result.ok === true ? null : (result.message || JSON.stringify(result)) } }];

const plan = $json.plan;
if (!plan) throw new Error('No hay plan guardado para el mensaje');
const workouts = (plan.workouts || []).map(w => '- ' + w.date + ' | ' + w.type + ' | ' + w.title + (w.targetDistanceMeters ? ' | ' + (w.targetDistanceMeters / 1000).toFixed(1) + ' km' : '')).join('
');
const text = '🏃 Plan semanal ' + plan.weekStart + ' (v' + plan.version + ')

' + (plan.summary || '') + '

' + workouts + '

Plan ID: ' + plan.planId;
return [{ json: { telegramText: text } }];

const p = $('Preparar llamadas MCP').item.json;
const error = $json.failError || $json.saveResult?.message || $json.error?.message || $json.message || 'Error generando el plan';
return [{ json: { ...p, failError: String(error) } }];

const p = $('Preparar fallo').item.json;
const text = '⚠️ No se pudo generar el plan semanal (' + p.weekStart + ').\n' + p.failError + '\nrequestId: ' + p.requestId;
return [{ json: { telegramText: text } }];
